/**
 * Build dist/morphink.css from src/styles/morphink.css entry file.
 *
 * 1. Read the entry file and inline all @import statements
 *    (resolves package paths via Node resolution and relative paths)
 * 2. Append dist/components.css (component-scoped styles, generated by Vite)
 * 3. Append dist/ui.css (scoped Tailwind utilities, generated by Tailwind CLI)
 * 4. Write the result to dist/morphink.css
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createRequire } from 'node:module'

const __dirname = dirname(fileURLToPath(import.meta.url))
const require = createRequire(import.meta.url)
const uiRoot = resolve(__dirname, '..')

const ENTRY = resolve(uiRoot, 'src/styles/morphink.css')
const COMPONENTS_CSS = resolve(uiRoot, 'dist/components.css')
const UI_CSS = resolve(uiRoot, 'dist/ui.css')
const OUT = resolve(uiRoot, 'dist/morphink.css')

/**
 * Resolve an @import specifier to an absolute file path.
 * - Relative paths (./foo) are resolved from the importing file's directory
 * - Package paths (@morphink/tokens/foo.css) are resolved via Node require.resolve
 */
function resolveImport(specifier, fromFile) {
  if (specifier.startsWith('.')) {
    return resolve(dirname(fromFile), specifier)
  }
  return require.resolve(specifier)
}

/**
 * Recursively inline @import statements in a CSS file.
 */
function inlineImports(filePath) {
  const css = readFileSync(filePath, 'utf8')
  return css.replace(
    /^@import\s+['"](.+?)['"];?\s*$/gm,
    (_match, specifier) => {
      const resolved = resolveImport(specifier, filePath)
      return inlineImports(resolved)
    },
  )
}

// Build
const banner = '/* morphink.css — auto-generated, do not edit */\n\n'
const inlined = inlineImports(ENTRY)
const components = readFileSync(COMPONENTS_CSS, 'utf8')
const ui = readFileSync(UI_CSS, 'utf8')
const output =
  banner +
  inlined +
  '\n/* --- components --- */\n' +
  components +
  '\n/* --- ui --- */\n' +
  ui

writeFileSync(OUT, output)
console.log(`build-morphink: ${OUT} (${output.split('\n').length} lines)`)
